-- Align Gemini's active database rubric with protagonist-profile-info.html.
-- Apply AFTER manage_protagonist_profile.sql and its prerequisites.
-- Run the entire file in Supabase SQL Editor as postgres.
-- This changes the active trait set to the guide's seven traits.
-- The existing update RPC clears affected baseline/profile scores and votes,
-- drops removed trait columns, and preserves moderator score locks.
-- An owner-only backup is captured first in axiom_profile_prompt_backup.
-- No Gemini calls are made here. Rebuild profiles afterwards in Admin Hub.
-- Re-running with this exact definition is a no-op.

begin;
select pg_advisory_xact_lock(718204619);

create schema if not exists axiom_profile_prompt_backup;
revoke all on schema axiom_profile_prompt_backup from public, anon, authenticated, service_role;
create table if not exists axiom_profile_prompt_backup.snapshots (
  backup_id bigint generated always as identity primary key,
  captured_at timestamptz not null default now(),
  definition_revision bigint not null,
  source_table text not null,
  row_data jsonb not null
);
alter table axiom_profile_prompt_backup.snapshots enable row level security;
-- No client policies: backup rows are available only to the database owner.
revoke all on all tables in schema axiom_profile_prompt_backup from public, anon, authenticated, service_role;
revoke all on all sequences in schema axiom_profile_prompt_backup from public, anon, authenticated, service_role;

do $migration$
declare
  current_def public.protagonist_definition;
  new_instructions text := $instructions$Score the identified protagonist using the trait definitions and all eleven anchors supplied for each trait. These are Axiom-specific scales; do not substitute generic personality scales or genre conventions. Return an integer from 0 to 100 for every requested trait; intermediate values are allowed when supported by the evidence. A score of 50 is not an automatic average unless that trait explicitly defines it that way.
Base scores on supplied synopsis, tags, genres, and reader comments. Distinguish demonstrated behavior from labels, reader opinions, and assumptions. Do not invent scenes, motives, relationships, or plot facts. Reference characters in the rubric illustrate the scale; they are not evidence about the novel being assessed.
Missing evidence is not evidence that a trait is absent. Do not automatically assign 0 or 50 when information is sparse. Make the most defensible estimate supported by the supplied material and lower confidence when any score is poorly supported. Explain important uncertainty in the evidence summary.
Evaluate recurring characterization and meaningful decisions, while honoring explicit single-scene exceptions in the anchors. In particular, credible evidence of even one genuine romantic or sexual preference rules out Romantic Attachment 0. Lack of romance tags, being single, prioritizing goals, or others being attracted to the protagonist does not establish 0.
Romantic Attachment includes both romantic and sexual desire under this guide; do not separate sexual desire into another trait. Arrogance & Conceit measures self-importance and ego-driven responses, not mere knowledge of one's abilities. Score each trait independently and apply the full range of its anchors.$instructions$;
  new_traits jsonb := $traits$[
  {
    "key": "intelligence",
    "name": "Intelligence",
    "prompt": "Intelligence is the smartness of a certain protagonist. This includes factors such as comprehension, wisdom, emotional intelligence, general knowledge, and scientific understanding. This can be shown by their actions in a certain novel, and how smart this protagonist is relative to all their peers. Whether this protagonist is outsmarting everyone or keeping up with other geniuses can be shown by certain events.\n\nAxiom scoring anchors:\n0: Represents an intelligence level of 0. It means that the protagonist is truly dense, acts without thinking, or in general doesn’t even think at all. There is no singular scene in the novel where the protagonist does something that is a reasonable decision by a smart person.\n\n10: Represents a protagonist who is extremely unintelligent. They might have a reasonable thought or make a good decision once in a while, but they usually fail to understand even simple situations. They make the same mistakes repeatedly, and rarely understand what they did wrong even after someone explains it to them.\n\n20: Represents a protagonist who is clearly lacking in intelligence. They can understand simple things and occasionally make a reasonable decision, but they struggle whenever a situation requires more thought. They are easily fooled by others, and their decisions often create problems that could have been avoided.\n\n30: Represents a protagonist of below average intelligence. They can think for themselves and understand what is happening around them, but they often miss obvious details or make decisions without considering the consequences. They have some smart moments, but their poor decisions are much more common.\n\n40: Represents a protagonist who is slightly below average in intelligence. They can make reasonable decisions in familiar situations, but they struggle when dealing with something complicated or unfamiliar. They might show intelligence in certain areas, but they are generally slower to understand things than an average person.\n\n50: Represents a character of average intelligence in a novel. There are some smart decisions that this protagonist makes, and there are also some very stupid decisions that they might make. In essence, they are considered similar to an average person whom you’d meet in real life.\n\n60: Represents a protagonist who is slightly above average in intelligence. They usually think before acting, pick up on details that others might miss, and make more smart decisions than stupid ones. They can understand complicated situations with some time, but they can still be outsmarted by someone more intelligent.\n\n70: Represents a protagonist who is clearly intelligent. They understand complicated ideas, learn from their mistakes, and usually consider the consequences of their actions. They can come up with good plans and outsmart most ordinary people, although they may still struggle against geniuses or in areas outside their knowledge.\n\n80: Represents a protagonist who is extremely intelligent and can be considered a genius in certain areas. They can understand things that most people would struggle with, come up with clever solutions, and outsmart other intelligent characters. However, they still have clear weaknesses in their intelligence, and being a genius in one area does not mean they are equally smart in every other area.\n\n90: Represents a protagonist who is one of the most intelligent characters in the series. They consistently show intelligence through their decisions, understand situations that even other smart characters miss, and can keep up with or outsmart other geniuses. Their intelligence covers most areas, although there may still be certain weaknesses or someone who can surpass them.\n\n100: Represents the peak of intelligence. This character is seen as the most intelligent character of the series, and consistently shows why through their actions and decisions. They also have extremely high intelligence in all forms, including wisdom, general knowledge, scientific understanding, street smartness, emotional intelligence, and the ability to read the atmosphere."
  },
  {
    "key": "charisma",
    "name": "Charisma",
    "prompt": "Charisma is how much a certain protagonist can attract, influence, or draw others towards them through their personality and presence. This includes factors such as confidence, charm, communication, leadership, and the ability to make others want to listen to them. This can be shown by their interactions in a certain novel, and how other characters respond to them. Whether this protagonist can inspire a crowd, convince someone to follow them, or make a strong impression can be shown by certain events. Being liked because of their strength, appearance, or status alone does not necessarily mean that they have high charisma.\n\nAxiom scoring anchors:\n0: Represents a charisma level of 0. It means that the protagonist has no charm or ability to draw others towards them through their personality. There is no singular scene in the novel where the protagonist convinces, inspires, or interests someone through their words or presence.\n\n10: Represents a protagonist who has extremely low charisma. They usually struggle to keep others interested in what they are saying, and their attempts to convince or inspire someone almost always fail. They might occasionally make a good impression, but this is very rare.\n\n20: Represents a protagonist who is clearly lacking in charisma. They can hold a simple conversation, but they struggle to connect with others or make their words have any influence. Others rarely look to them for guidance, and they are usually ignored when someone more charismatic is present.\n\n30: Represents a protagonist of below average charisma. They can connect with certain people and occasionally convince someone, but they often struggle to hold attention or make a strong impression. They have some charming moments, but these are uncommon.\n\n40: Represents a protagonist who is slightly below average in charisma. They can make a decent impression once they are comfortable with someone, but they struggle to draw people towards them in unfamiliar situations. They might be charismatic around close friends, but this does not usually extend to other people.\n\n50: Represents a character of average charisma in a novel. There are some moments where this protagonist is charming or convincing, and there are also moments where they are awkward or fail to get their point across. In essence, they are considered similar to an average person whom you’d meet in real life.\n\n60: Represents a protagonist who is slightly above average in charisma. They usually leave a good impression, can keep others interested in a conversation, and are reasonably convincing. People tend to enjoy being around them, although they might struggle to influence a larger group or someone who strongly disagrees with them.\n\n70: Represents a protagonist who is clearly charismatic. They can draw others towards them, speak with confidence, and make people want to listen. They can convince others to consider their views and inspire people to follow them, although their influence still has clear limits.\n\n80: Represents a protagonist who is extremely charismatic. They can hold the attention of a crowd, win over people who were initially doubtful, and inspire strong loyalty through their personality. Their words and presence have a clear effect on others, although there are still certain people or situations where their charisma falls short.\n\n90: Represents a protagonist who is one of the most charismatic characters in the series. They consistently draw attention, inspire others, and convince people who would usually be difficult to reach. They can bring together people with different views and make others want to follow them even in difficult situations. However, their influence is not always enough to win someone over.\n\n100: Represents the peak of charisma. This character is seen as the most charismatic character of the series, and consistently shows why through their interactions with others. They have extremely high charm, confidence, communication, leadership, and ability to inspire. Their words and presence can influence entire groups, create lasting loyalty, and make even their opponents respect or admire them."
  },
  {
    "key": "courage",
    "name": "Courage",
    "prompt": "Courage is how well a certain protagonist withstands adversity and handles themselves in difficult situations. This includes factors such as bravery, composure, patience, resilience, and the ability to keep going when things go wrong. This can be shown by their actions in a certain novel, and how they react to fear, pressure, frustration, failure, or loss. Whether this protagonist falls apart when something happens or remains steady through what they are experiencing can be shown by certain events. Feeling afraid, angry, or upset does not automatically mean that they have low courage. What matters is how they handle these feelings, how much control they have over their actions, and whether they can continue despite them.\n\nAxiom scoring anchors:\n0: Represents a courage level of 0. It means that the protagonist cannot withstand even the smallest amount of adversity. They immediately panic, lose control, or give up whenever something becomes difficult. There is no singular scene in the novel where the protagonist shows bravery, composure, patience, or the ability to endure a setback.\n\n10: Represents a protagonist who has extremely low courage. Even minor problems can overwhelm them, and they almost always need someone else to reassure them or handle the situation. They might occasionally endure something uncomfortable, but their ability to remain steady disappears as soon as the pressure increases.\n\n20: Represents a protagonist who is clearly lacking in courage. They can handle small difficulties when they have enough support, but fear, frustration, or disappointment easily takes control of their actions. They struggle to recover from setbacks and often abandon something once it becomes painful or uncertain.\n\n30: Represents a protagonist of below average courage. They have some moments where they remain composed or push through a difficult situation, but they are inconsistent. They might endure the initial problem, only to lose patience, act impulsively, or give up when things continue going wrong.\n\n40: Represents a protagonist who is slightly below average in courage. They can handle ordinary difficulties, but unexpected pressure or repeated setbacks often gets the better of them. They can recover and continue with some time or encouragement, although they struggle to remain steady while the situation is happening.\n\n50: Represents a character of average courage in a novel. There are some moments where this protagonist is brave, patient, and composed, and there are also moments where they panic, lose their temper, or struggle to continue. They can recover from difficulties, but serious adversity can leave them shaken. In essence, they are considered similar to an average person whom you’d meet in real life.\n\n60: Represents a protagonist who is slightly above average in courage. They usually keep themselves under control when something goes wrong and can continue despite fear, frustration, or disappointment. They recover from most setbacks without needing much encouragement, although serious pressure can still overwhelm them.\n\n70: Represents a protagonist who clearly has strong courage. They can face danger, endure hardship, and remain patient when things do not go their way. Their feelings do not easily take control of their decisions, and they usually look for a way forward instead of falling apart. However, certain fears, losses, or repeated failures can still cause them to waver.\n\n80: Represents a protagonist who has extremely high courage. They remain composed through serious danger, suffering, and prolonged uncertainty. They can endure repeated setbacks without becoming reckless or giving up, and they continue making considered decisions even when they are deeply affected by what is happening. There are still certain situations that can break their composure, but reaching that point takes a great deal.\n\n90: Represents a protagonist who is one of the most courageous and resilient characters in the series. Extreme fear, pain, humiliation, or loss rarely takes control of their actions. They can withstand situations that would break most people and continue with patience and a clear mind. They might still experience a moment of wavering, but almost nothing keeps them from regaining their composure and moving forward.\n\n100: Represents the peak of courage. This character remains completely steady regardless of the adversity they face. Fear, suffering, failure, loss, and uncertainty do not take control of their judgement or break their resolve. They can endure what is happening, accept when something has gone wrong, and calmly decide what to do next. This does not mean that they blindly continue with a failed plan. They can retreat, change their approach, or abandon something without being driven by panic, frustration, or despair."
  },
  {
    "key": "moral_integrity",
    "name": "Moral Integrity",
    "prompt": "Moral Integrity is how strongly a certain protagonist follows moral principles, and how much their actions show honesty, fairness, compassion, and responsibility. This includes how they treat others, whether they take responsibility for their mistakes, and whether they still do what is right when it comes at a personal cost. This can be shown by their actions in a certain novel, especially when doing the wrong thing would be easier or more rewarding. Simply following their own beliefs does not necessarily mean that they have high moral integrity if those beliefs excuse cruelty or harming innocent people.\n\nAxiom scoring anchors:\n0: Represents a moral integrity level of 0. It means that the protagonist has no concern for what is right or wrong, and willingly lies, betrays, exploits, or harms innocent people whenever it suits them. There is no singular scene in the novel where the protagonist shows a sincere concern for doing what is right.\n\n10: Represents a protagonist who has extremely low moral integrity. They usually act for their own benefit regardless of who gets hurt. They might occasionally show guilt or do something decent, but this rarely changes how they treat others.\n\n20: Represents a protagonist who is clearly lacking in moral integrity. They have some sense of right and wrong, but they easily put it aside for personal gain or convenience. They might care about certain people while having little concern for the harm they cause to anyone else.\n\n30: Represents a protagonist of below average moral integrity. They can make moral decisions and sometimes feel responsible for their actions, but they frequently excuse dishonesty, unfairness, or cruelty when it benefits them. Their principles often give way when following them becomes difficult.\n\n40: Represents a protagonist who is slightly below average in moral integrity. They usually prefer to do the right thing when it is easy, but they sometimes act selfishly or avoid responsibility when there is a personal cost. They have a conscience, although they do not always listen to it.\n\n50: Represents a character of average moral integrity in a novel. There are some moments where this protagonist is honest, fair, and considerate, and there are also moments where they act selfishly or make excuses for something they know is wrong. In essence, they are considered similar to an average person whom you’d meet in real life.\n\n60: Represents a protagonist who is slightly above average in moral integrity. They usually try to be honest, treat others fairly, and take responsibility when they make a mistake. They are willing to accept some personal cost to do what is right, although serious pressure can still cause them to compromise.\n\n70: Represents a protagonist who clearly has strong moral integrity. Their actions usually match their principles, and they are willing to give up personal benefits rather than knowingly mistreat others. They admit when they are wrong and try to make things right, although there are still situations where their morals are tested.\n\n80: Represents a protagonist who has extremely strong moral integrity. They consistently choose honesty, fairness, and compassion even when doing so creates serious problems for them. They refuse most opportunities to benefit from harming others, although certain pressures or personal attachments can still cause them to fall short.\n\n90: Represents a protagonist who is one of the most morally upright characters in the series. They hold to their principles through extreme pressure, temptation, or personal loss. They show concern even for people outside their own circle, and rarely excuse their own wrongdoing simply because they had good intentions.\n\n100: Represents the peak of moral integrity. This character consistently does what is right even when it could cost them everything. Their honesty, fairness, compassion, and willingness to take responsibility extend to everyone, including people they dislike. They do not abandon their morals for power, convenience, loyalty, or personal gain."
  },
  {
    "key": "kinship_friendship",
    "name": "Kinship & Friendship",
    "prompt": "Kinship & Friendship is how much a certain protagonist values their bonds with family, friends, and people they consider close to them. This includes factors such as loyalty, trust, emotional closeness, support, and the willingness to put effort into these relationships. This can be shown by their actions in a certain novel, whether they are able to sacrifice or go out of their way for these people, and how much the protagonist values these bonds.\n\nAxiom scoring anchors:\n0: Represents a kinship and friendship level of 0. It means that the protagonist has no attachment to family or friends, and places no value on forming or maintaining these bonds. There is no singular scene in the novel where the protagonist shows any care for someone as a family member or friend. They may only make alliances based on mutual benefits, but not for the sake of friendship or kinship.\n\n10: Represents a protagonist who places extremely little value on kinship and friendship. They might show a small attachment to someone, but they usually treat relationships as something disposable or useful. They make almost no effort to support others or keep these bonds.\n\n20: Represents a protagonist who is clearly lacking in attachment to family and friends. They have some genuine care for certain people, but these relationships rarely affect their decisions. They are usually unwilling to accept inconvenience or put much effort into maintaining them.\n\n30: Represents a protagonist who places below average value on kinship and friendship. They can enjoy being around people close to them and occasionally offer support, but they often neglect these relationships. Their loyalty and involvement are inconsistent, especially when they have other priorities.\n\n40: Represents a protagonist who places slightly below average value on kinship and friendship. They care about their family or friends, but they can be distant or unreliable when these people need them. They make some effort to maintain their bonds, although they often leave that effort to the other person.\n\n50: Represents a character with an average attachment to family and friends in a novel. There are some moments where this protagonist is loyal, caring, and supportive, and there are also moments where they neglect these relationships or put themselves first. In essence, they are considered similar to an average person whom you’d meet in real life.\n\n60: Represents a protagonist who places slightly above average value on kinship and friendship. They usually make time for the people close to them, offer support, and put effort into keeping their relationships. They are willing to make some sacrifices for these people, although there are limits to how much they will give.\n\n70: Represents a protagonist who clearly values kinship and friendship. They are loyal, involved, and willing to stand by the people close to them through difficult situations. These bonds have a strong influence on their decisions, although certain conflicts or personal goals can still take priority.\n\n80: Represents a protagonist who places extremely high value on kinship and friendship. They form deep bonds and consistently put effort into supporting and protecting the people close to them. They are willing to make serious sacrifices for these relationships, although there are still certain things they would struggle to give up.\n\n90: Represents a protagonist whose bonds with family or friends are among the strongest in the series. These relationships are central to their life, and they remain deeply committed through distance, conflict, danger, or personal loss. They rarely abandon someone close to them simply because staying becomes difficult.\n\n100: Represents the peak of kinship and friendship. This character’s bonds with family or friends are among the most important things in their life, and their actions consistently show this. They show extremely high loyalty, care, trust, and commitment, and are willing to risk everything for the people they consider their own."
  },
  {
    "key": "romantic_attachment",
    "name": "Romantic Attachment",
    "prompt": "Romantic Attachment is how much a certain protagonist is affected by romantic and sexual desire. This includes factors such as love, crushes, lust, sexual urges, wanting a partner, and treating someone differently because of attraction or their gender. This can be shown by their thoughts and actions in a certain novel, even if these feelings never develop into a relationship. Whether this protagonist remains completely unfaltered or allows these desires to influence their decisions can be shown by certain events.\n\nBeing single, cold, or focused on their goals does not mean that a protagonist has no romantic attachment. A protagonist can place their ambitions above romance and still have sexual desires or make exceptions for someone they find attractive. Someone else being attracted to the protagonist does not count unless the protagonist feels something themselves. Neither does pretending to be attracted to someone for a certain purpose.\n\nAxiom scoring anchors:\n0: Represents a romantic attachment level of 0. It means that the protagonist is completely unfaltered and unwavering when it comes to romantic or sexual desire. They see every human as identical and genderless in this regard. They can recognise beauty as a fact, but feel no attraction towards it. There is no singular scene in the novel where the protagonist expresses a genuine romantic or sexual preference, feels desire, or gives someone different treatment because of these feelings or their gender. Even a single scene like this means that they are not 0. This score is extremely rare. Fang Yuan from Reverend Insanity and the protagonist of Starless Sanity are the reference points for what I mean by 0.\n\n10: Represents a protagonist who has extremely low romantic attachment, but is not completely free from it. There might be a single moment where they express attraction, feel a sexual urge, or show a preference that separates them from 0. These moments are extremely rare and have almost no influence on their actions, but they still exist.\n\n20: Represents a protagonist who has low romantic attachment. They occasionally feel attraction or sexual desire, although they usually move past it without much thought. These feelings do not have much influence on their goals, but the protagonist is still affected by them and cannot be considered completely detached.\n\n30: Represents the kind of protagonist that many readers would usually describe as cold or having no romance. Their goals come first, but they can still feel lust, have sex, express attraction, or treat someone differently because of their gender or desirability. A protagonist like the one from WMW would be around this point. Being willing to abandon a relationship for their goals does not erase the desire they had in the first place.\n\n40: Represents a protagonist whose romantic or sexual desires appear more regularly. They notice people they find attractive, enjoy receiving their attention, or sometimes seek intimacy. Their main goals still take priority, but these desires have a noticeable place in their thoughts and occasionally influence how they treat others.\n\n50: Represents a protagonist whose romantic or sexual desires are a recurring part of their life. They might pursue someone, want a partner, seek sex, or develop an attachment that matters to them. These feelings influence some of their decisions, even if they can still put them aside for something more important. This is not necessarily the average protagonist, because this scale is not based on what most novels consider normal.\n\n60: Represents a protagonist whose romantic or sexual desires have a clear influence on their behaviour. They regularly think about someone they want, seek opportunities to be close to them, or give them treatment they would not give to someone else. They begin making meaningful exceptions or changing plans because of these feelings.\n\n70: Represents a protagonist who has strong romantic attachment or sexual desire. These feelings repeatedly affect their judgement and priorities. They might delay their goals, accept avoidable risks, or overlook something they would otherwise object to because they are attracted or attached to the person involved.\n\n80: Represents a protagonist who is heavily influenced by romantic attachment or lust. These feelings are difficult for them to put aside, even when they interfere with something important. They repeatedly make significant sacrifices or compromise their own judgement because of the person they love or desire.\n\n90: Represents a protagonist whose romantic or sexual desires are among their main motivations. Many important decisions come back to obtaining, keeping, pleasing, or protecting someone they are attached to or want. Their goals and principles frequently give way when these feelings are involved.\n\n100: Represents a protagonist whose romantic attachment or sexual desire consistently determines major parts of their life. These feelings repeatedly take priority over their judgement, ambitions, or other commitments. This is not the total ceiling of romantic attachment or lust, and it does not mean the strongest desire imaginable. It is the upper reference point within Axiom’s scale. The lust-driven and degenerate novels excluded from Axiom can go beyond this point, and in my view, most novels fall into that territory."
  },
  {
    "key": "arrogance_pride",
    "name": "Arrogance & Conceit",
    "prompt": "Arrogance & Conceit is how much importance a certain protagonist places on themselves and their ego. This includes factors such as pride, self-importance, taking offence, holding grudges, and the need for revenge when they feel wronged. This can be shown by their actions in a certain novel, and how they react when someone insults, humiliates, disrespects, or harms them. Whether this protagonist can let something go or feels that every offence must be repaid can be shown by certain events. This has nothing to do with how much they believe in their own abilities. A protagonist can know exactly how capable they are while placing very little importance on themselves.\n\nAxiom scoring anchors:\n0: Represents an arrogance and conceit level of 0. It means that the protagonist has no ego and considers themselves equal to everything, including other people, animals, plants, and even inanimate objects. They do not consider their own existence more important than anything else. Insults and humiliation do not hurt their pride, and they feel no need to seek revenge for a personal offence because there is no sense of self-importance to defend.\n\n10: Represents a protagonist who has extremely low arrogance and conceit. They place almost no importance on their own pride and rarely feel personally offended. They might still have a small attachment to their own importance, but they almost never feel the need to defend it or make someone pay for disrespecting them.\n\n20: Represents a protagonist who has low arrogance and conceit. They do not see themselves as particularly important and can let go of most insults or personal offences. They might occasionally feel their pride being hurt, but they rarely hold onto these feelings or act out of a desire for revenge.\n\n30: Represents a protagonist of below average arrogance and conceit. They have some pride and can feel offended when someone humiliates or wrongs them, but they usually move past it. They might hold a grudge over something serious, although they do not often feel that their dignity needs to be defended.\n\n40: Represents a protagonist who is slightly below average in arrogance and conceit. They care somewhat about how they are treated and can take disrespect personally. They might want an apology or feel the urge to get back at someone, but they can usually let things go without needing the other person to suffer.\n\n50: Represents a character of average arrogance and conceit in a novel. There are some moments where this protagonist takes offence, holds a grudge, or wants revenge, and there are also moments where they put their pride aside and move on. In essence, they are considered similar to an average person whom you’d meet in real life.\n\n60: Represents a protagonist who is slightly above average in arrogance and conceit. Their pride has a noticeable influence on their decisions, and they find it difficult to ignore being insulted or wronged. They often hold grudges and want to repay personal offences, although they can still decide that something is not worth pursuing.\n\n70: Represents a protagonist who clearly has strong arrogance and conceit. They place considerable importance on themselves and how others treat them. They take disrespect seriously, struggle to let go of humiliation, and often seek revenge when they feel wronged. Letting an offence go can feel like accepting that someone is allowed to treat them as lesser.\n\n80: Represents a protagonist who has extremely high arrogance and conceit. Their sense of self-importance makes even small offences difficult to forgive. They are willing to go to serious lengths to restore their pride or take revenge, even when doing so costs them something much more valuable than the original offence.\n\n90: Represents a protagonist who is one of the most arrogant and conceited characters in the series. They consider their own importance far above that of almost everything around them, and rarely tolerate an insult or personal offence going unanswered. Their grudges are lasting, and they are willing to cause extreme suffering over something that wounded their ego.\n\n100: Represents the peak of arrogance and conceit. This character places their own importance above everything else. Any insult, humiliation, or act against them is seen as unacceptable, no matter how small. They feel entitled to whatever response satisfies their pride, regardless of the consequences for anyone else. They would rather sacrifice everything around them than accept an offence against themselves."
  }
]$traits$::jsonb;
begin
  select * into strict current_def
    from public.protagonist_definition where id for update;
  if current_def.instructions = new_instructions and current_def.traits = new_traits then
    raise notice 'Guide prompts are already installed; no scores or votes changed.';
    return;
  end if;

  -- Use the same profile lock as the supported definition-update function.
  lock table public.protagonist_profiles in access exclusive mode;
  lock table public.protagonist_baselines, public.protagonist_votes in share row exclusive mode;

  insert into axiom_profile_prompt_backup.snapshots(definition_revision, source_table, row_data)
    values(current_def.revision, 'protagonist_definition', to_jsonb(current_def));
  insert into axiom_profile_prompt_backup.snapshots(definition_revision, source_table, row_data)
    select current_def.revision, 'protagonist_profiles', to_jsonb(p) from public.protagonist_profiles p;
  insert into axiom_profile_prompt_backup.snapshots(definition_revision, source_table, row_data)
    select current_def.revision, 'protagonist_baselines', to_jsonb(b) from public.protagonist_baselines b;
  insert into axiom_profile_prompt_backup.snapshots(definition_revision, source_table, row_data)
    select current_def.revision, 'protagonist_votes', to_jsonb(v) from public.protagonist_votes v;

  -- Preserve validation, revision handling, column changes, and invalidation.
  perform public.update_protagonist_definition(current_def.revision, new_instructions, new_traits);
  raise notice 'Installed guide prompts. Previous data backed up at revision %. Rebuild profiles next; moderator locks remain.', current_def.revision;
end;
$migration$;

commit;

-- Confirm the active trait order and prompt sizes.
select d.revision, t.ordinality as position, t.trait->>'key' as trait_key,
  t.trait->>'name' as trait_name, length(t.trait->>'prompt') as prompt_characters
from public.protagonist_definition d,
  lateral jsonb_array_elements(d.traits) with ordinality as t(trait, ordinality)
where d.id
order by t.ordinality;
